class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(values):
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = [root]
    i = 1
    while i < len(values) and queue:
        node = queue.pop(0)
        if i < len(values):
            if values[i] is not None:
                node.left = TreeNode(values[i])
                queue.append(node.left)
            i += 1
        if i < len(values):
            if values[i] is not None:
                node.right = TreeNode(values[i])
                queue.append(node.right)
            i += 1
    return root


def binary_tree_paths(root):
    if root is None:
        return []
    if root.left is None and root.right is None:
        return [str(root.val)]

    paths = []
    for child_paths in (binary_tree_paths(root.left), binary_tree_paths(root.right)):
        for p in child_paths:
            paths.append(str(root.val) + "->" + p)
    return paths


if __name__ == "__main__":
    tree1 = build_tree([1, 2, 3, None, 5])
    print(binary_tree_paths(tree1))
    tree2 = build_tree([1])
    print(binary_tree_paths(tree2))

