import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static TreeNode buildTree(Integer[] values) {
        if (values.length == 0 || values[0] == null) return null;
        TreeNode root = new TreeNode(values[0]);
        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        int i = 1;
        while (i < values.length && !queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (i < values.length) {
                if (values[i] != null) { node.left = new TreeNode(values[i]); queue.add(node.left); }
                i++;
            }
            if (i < values.length) {
                if (values[i] != null) { node.right = new TreeNode(values[i]); queue.add(node.right); }
                i++;
            }
        }
        return root;
    }

    static List<String> binaryTreePaths(TreeNode root) {
        List<String> paths = new ArrayList<>();
        if (root == null) return paths;
        if (root.left == null && root.right == null) {
            paths.add(String.valueOf(root.val));
            return paths;
        }
        for (String p : binaryTreePaths(root.left)) paths.add(root.val + "->" + p);
        for (String p : binaryTreePaths(root.right)) paths.add(root.val + "->" + p);
        return paths;
    }

    public static void main(String[] args) {
        TreeNode tree1 = buildTree(new Integer[]{1, 2, 3, null, 5});
        System.out.println(binaryTreePaths(tree1));
        TreeNode tree2 = buildTree(new Integer[]{1});
        System.out.println(binaryTreePaths(tree2));
    }
}

