#include <bits/stdc++.h>
using namespace std;

struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

TreeNode* buildTree(vector<int>& values, vector<bool>& isNull) {
    if (values.empty() || isNull[0]) return nullptr;
    TreeNode* root = new TreeNode(values[0]);
    queue<TreeNode*> q;
    q.push(root);
    int i = 1;
    while (i < (int)values.size() && !q.empty()) {
        TreeNode* node = q.front(); q.pop();
        if (i < (int)values.size()) { if (!isNull[i]) { node->left = new TreeNode(values[i]); q.push(node->left); } i++; }
        if (i < (int)values.size()) { if (!isNull[i]) { node->right = new TreeNode(values[i]); q.push(node->right); } i++; }
    }
    return root;
}

vector<string> binaryTreePaths(TreeNode* root) {
    vector<string> paths;
    if (!root) return paths;
    if (!root->left && !root->right) {
        paths.push_back(to_string(root->val));
        return paths;
    }
    for (auto& p : binaryTreePaths(root->left)) paths.push_back(to_string(root->val) + "->" + p);
    for (auto& p : binaryTreePaths(root->right)) paths.push_back(to_string(root->val) + "->" + p);
    return paths;
}

int main() {
    vector<int> vals1 = {1, 2, 3, 0, 5};
    vector<bool> null1 = {false, false, false, true, false};
    TreeNode* tree1 = buildTree(vals1, null1);
    for (auto& p : binaryTreePaths(tree1)) cout << p << " ";
    cout << endl;
    return 0;
}

